  const avg = days.reduce((a, d) => a + (d.price_de_mean ?? 0), 0) / (days.length || 1);

  // the regulator's modelled industrial price for the latest month in the window
  const month = (days.at(-1)?.date || "").slice(0, 7);
  const ip = ref?.industrial_prices_eur_mwh?.slice().reverse()
               .find(r => r.month <= month) || null;
  const pol = ref?.industriestrompreis_policy || null;

