    earned && ["Germany earned on its own output", earned, "day-ahead, export hours", "var(--in)"],
  ].filter(r => r && r[1] != null).sort((a, b) => b[1] - a[1]);
  if (rows.length < 3) { host.replaceChildren(); return false; }

  const ROW = 30, L = 210, W = host.clientWidth || 720, H = rows.length * ROW + 16;
  const svg = el("svg", { viewBox: `0 0 ${W} ${H}`, width: W, height: H, role: "img",
