function drawWind(host, adj) {
  const prof = adj?.profile;
  if (!prof) { host.replaceChildren(); return false; }
  const lags = ["-3", "-2", "-1", "0", "1", "2", "3"].filter(k => prof[k]);
  if (lags.length < 3) { host.replaceChildren(); return false; }

