def align(s: pd.Series, freq: str) -> pd.Series:
    """Put a series on a common time grid.

    Both backends hand back mixed resolutions -- day-ahead moved to 15-minute
    MTUs in late 2025 while plenty of flow series are still hourly, and some
    borders report in 30-minute steps. Downsampling averages (prices and MW
    flows are both interval averages, so the mean is the correct aggregate);
    upsampling forward-fills.
    """
    if s is None or s.empty:
        return pd.Series(dtype="float64")
    s = s.sort_index()
    s.index = (s.index.tz_localize(TZ) if s.index.tz is None
               else s.index.tz_convert(TZ))
    return s.resample(freq).mean().ffill()


def collect(backend: Backend, start, end, freq: str, physical: bool,
            neighbours: list) -> pd.DataFrame:
    """One row per MTU per border, flows in MW, prices in EUR/MWh.

    Raises LookupError when the window comes back unusable; over a range that
    is one chunk to warn about, not a reason to abandon the run.

def _fetch(self, modules: list, start, end, resolution="hour",
           region: str | None = None) -> dict:
    """POST once for many modules; returns {column label: Series} in local time."""
    region = region or self.REGION
    body = {"request_form": [{
        "format": "CSV", "moduleIds": list(modules), "region": region,
        "timestamp_from": self._ms(start), "timestamp_to": self._ms(end),
        "type": "discrete", "language": "de", "resolution": resolution,
    }]}
    # cache on the request's meaning, with `end` in a form Cache.settled reads
    key = Cache.key(self.DOWNLOAD, {"modules": ",".join(map(str, sorted(modules))),
                                    "region": region, "res": resolution,
                                    "start": start.isoformat(), "end": end.isoformat()})
    text = self.cache.get(key) if self.cache else None
    if text == MISSING:
        raise LookupError("no SMARD data (cached)")
    if text is None:
        r = self.s.post(f"{self.BASE}{self.DOWNLOAD}", json=body, timeout=self.timeout)
        r.raise_for_status()
        text = r.text
        if self.cache:
            self.cache.put(key, text, {"end": end.isoformat()})

    import csv as _csv
    rows = list(_csv.reader(text.lstrip("﻿").splitlines(), delimiter=";"))
    if not rows or len(rows[0]) < 3:
        raise LookupError("SMARD returned no columns")
    header = rows[0][2:]
    stamps, cols = [], [[] for _ in header]
    for r in rows[1:]:
        if len(r) < 3 or not r[0].strip():
            continue
        if "Keine Daten" in r[0]:
            raise LookupError(f"SMARD: no data for {start.date()}..{end.date()} "
                              f"(region {region})")
        stamps.append(r[0].strip())
        for i in range(len(header)):
            cols[i].append(self._de_num(r[2 + i]) if 2 + i < len(r) else float("nan"))
    if not stamps:
        raise LookupError("SMARD returned no rows")

    # daily and coarser resolutions come back without a time component
    try:
        idx = pd.to_datetime(stamps, format="%d.%m.%Y %H:%M")
    except ValueError:
        idx = pd.to_datetime(stamps, format="%d.%m.%Y")
    # local wall-clock timestamps; infer the repeated hour when clocks go back
    idx = idx.tz_localize(TZ, ambiguous="infer", nonexistent="shift_forward")

    # SMARD reports energy *per interval*, so MWh equals the MW average only at
    # hourly resolution. Scale by the interval actually returned, and read the
    # unit off the header so a EUR/MWh price is never scaled.
    step = (idx.to_series().diff().dropna().median().total_seconds() / 60
            if len(idx) > 1 else 60.0)
    to_mw = 60.0 / step

    out = {}
    for label, col in zip(header, cols):
        # "Dänemark 1 (Export) [MWh] Berechnete Auflösungen" -> "Dänemark 1 (Export)"
        name = label.split("[")[0].strip()
        if name in out:
            raise LookupError(f"SMARD returned duplicate column {name!r}")
        ser = pd.Series(col, index=idx, dtype="float64")
        if "[MWh]" in label:
            ser = ser * to_mw
        out[name] = ser
    return out

