    "aria-label": "Price gap, net position and solar capture price by month, showing the "
      + "summer and winter systems differ" });
  const x0 = PAD.l, x1 = W - PAD.r;
  const band = (x1 - x0) / ms.length;
  const bw = Math.min(34, barW(band));

