    { key: "price_gap", title: "Price gap, importing hours minus exporting", unit: "€/MWh",
      diverging: false },
    { key: "net_import_gwh", title: "Net position", unit: "GWh", diverging: true,
      hi: "net importer", lo: "net exporter" },
